places = city.sites()
for place in places[:4]:
    city.place_hub(place)

places = city.sites()
best = sorted(places, key=lambda p: p.families_nearby, reverse=True)
chosen = []
for place in best:
    if len(chosen) == 4:
        break
    too_close = False
    for other in chosen:
        if abs(place.lat - other.lat) < 0.01 and abs(place.lon - other.lon) < 0.01:
            too_close = True
    if not too_close:
        chosen.append(place)
        city.place_hub(place)

